import os
from typing import List, Dict, Any
from mindee import Client, documents

def extract_table_cells_and_rows(file_path: str) -> List[Dict[str, Any]]:
    mindee_client = Client(api_key=os.environ["MINDEE_API_KEY"])

    with open(file_path, "rb") as file_handle:
        input_doc = mindee_client.doc_from_file(file_handle)

    result = input_doc.parse(documents.TypeReceiptV5)

    tables = []
    for page in result.document.pages:
        for table in page.tables:
            rows = []
            for row_idx, row in enumerate(table.rows):
                cells = []
                for cell in row.cells:
                    cells.append({
                        "text": cell.content,
                        "row_index": row_idx,
                        "col_index": cell.column_index,
                        "bounding_box": [
                            {"x": vertex.x, "y": vertex.y}
                            for vertex in cell.bounding_box.vertices
                        ] if cell.bounding_box else None
                    })
                rows.append({
                    "row_index": row_idx,
                    "cells": cells
                })
            tables.append({
                "page_number": page.idx,
                "rows": rows
            })

    return tables
